import{_ as t,c as o,o as r,ah as a}from"./chunks/framework.PvdZnrZd.js";const d=JSON.parse('{"title":"SELLER BUYER CHAT","description":"SELLER BUYER CHAT","frontmatter":{"title":"SELLER BUYER CHAT","description":"SELLER BUYER CHAT","date":"2025-07-29T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/seller-add-ons/seller-buyer-chat.md","filePath":"zenith/featured-app/seller-add-ons/seller-buyer-chat.md"}'),l={name:"zenith/featured-app/seller-add-ons/seller-buyer-chat.md"};function n(s,e,p,i,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<p><a href="https://webkul.com/blog/chatwhizz-communication-solution-for-your-organization/" target="_blank" rel="noreferrer">ChatWhizz</a> is now integrated with the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-seller-buyer-chat-new-theme/" target="_blank" rel="noreferrer">Seller-Buyer Chat</a> add-on of the <a href="https://apps.shopify.com/multi-vendor-marketplace" target="_blank" rel="noreferrer">Multivendor Marketplace App</a> for Shopify.</p><p>Using this integration, you can display a live chat widget on your storefront. The customers can connect with the sellers on the runtime and get their queries resolved.</p><h2 id="chatwhizz-registration" tabindex="-1">ChatWhizz Registration <a class="header-anchor" href="#chatwhizz-registration" aria-label="Permalink to &quot;ChatWhizz Registration&quot;">​</a></h2><p><strong>How to get registered on ChatWhizz(Registration Process)</strong><br> Read the <a href="https://webkul.com/blog/how-to-get-registration-on-chatwhizz/" target="_blank" rel="noreferrer">blog</a> to the end to learn how to register on ChatWhizz!</p><h2 id="installation-at-chatwhizz-end-seller-buyer-chat-add-on" tabindex="-1">Installation at ChatWhizz End: Seller-Buyer Chat Add-on <a class="header-anchor" href="#installation-at-chatwhizz-end-seller-buyer-chat-add-on" aria-label="Permalink to &quot;Installation at ChatWhizz End: Seller-Buyer Chat Add-on&quot;">​</a></h2><p>To install the add-on, visit the <strong>Admin Panel</strong> of <strong>ChatWhizz</strong>. From here, click on the <strong>Add-ons</strong> menu from the left navigation bar. On this redirected page, you’ll have the add-on listed.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/sellerbuyerchat1-1-1200x603.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/sellerbuyerchat1-1-1200x603.webp" alt="Seller buyer chat"></a></p><p>There are different plans to choose from. You can opt for a plan that is suitable for your business needs.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/08/r6-1004x1024.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/08/r6-1004x1024.png" alt="r6"></a></p><h2 id="installation-at-multivendor-marketplace-end-seller-buyer-chat-add-on" tabindex="-1">Installation at Multivendor Marketplace End: Seller-Buyer Chat Add-on <a class="header-anchor" href="#installation-at-multivendor-marketplace-end-seller-buyer-chat-add-on" aria-label="Permalink to &quot;Installation at Multivendor Marketplace End: Seller-Buyer Chat Add-on&quot;">​</a></h2><p>To install the add-on, visit <strong>Multivendor Marketplace Admin Panel</strong> &gt; Hover over the <strong>three dots</strong> on the top right of the dashboard &gt; <strong>Feature Apps</strong>. Next, enable the <strong>Seller-Buyer Chat</strong> add-on:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/addsellerbuyer.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/addsellerbuyer.webp" alt="r9"></a></p><p>Once enabled, visit <strong>Configuration</strong> &gt; <strong>Seller Buyer Chat</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/configurationsellerbuyer.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/configurationsellerbuyer.webp" alt="image-25"></a></p><p>Next, you need to configure the add-on by entering the following details:</p><ul><li>Email ID (Admin needs to mention marketplace admin email ID)</li><li>Access Token</li><li>Refresh Token</li></ul><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/apiseller.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/apiseller.webp" alt="c2"></a></p><p>To get the access token and refresh token, visit <strong>ChatWhizz admin &gt; installed add-ons &gt; seller buyer chat &gt; API details:</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/apidetails-1-1200x603.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/apidetails-1-1200x603.webp" alt="API"></a></p><p>Here, you will have both the keys:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/expirydate-1-1200x603.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/expirydate-1-1200x603.webp" alt="Expiry"></a></p><p>Once you&#39;ll save the details, you will get this success message on the screen:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/savedconfig.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/savedconfig.webp" alt="c3"></a></p><p>NOTE:</p><p>If the admin enables <strong>Allow Sellers to Configure this Feature</strong> tab, then the seller will be able to see and configure the seller-buyer chat on the seller panel.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatconfig.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatconfig.webp" alt="c5"></a></p><p>But if the admin disables &quot;<strong>Allow Sellers to Configure this Feature</strong>&quot; tab, then the seller will not be able to configure.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatsellerend.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatsellerend.webp" alt="c4"></a></p><h2 id="auto-login-to-seller-buyer-chat" tabindex="-1">Auto-login to Seller-Buyer Chat <a class="header-anchor" href="#auto-login-to-seller-buyer-chat" aria-label="Permalink to &quot;Auto-login to Seller-Buyer Chat&quot;">​</a></h2><p>Sellers can now auto-login to the Chatwhizz panel from within their own seller panel.</p><p>They will find the option under Seller panel&gt;&gt; Configuration&gt;&gt;Seller-Buyer Chat&gt;&gt; Chat login</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatlogin.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatlogin.webp" alt="screenshot_1696409564787"></a></p><h2 id="code-instructions" tabindex="-1">Code Instructions <a class="header-anchor" href="#code-instructions" aria-label="Permalink to &quot;Code Instructions&quot;">​</a></h2><p>Furthermore, visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Instructions for Marketplace</strong>.</p><p>Here, you will have the code to add to the <strong>footer.liquid</strong> (or theme.liquid) template to display the chat box on frontend:</p><p>To show Chat History on the Storefront Customer Account page, you need to add the codes in <strong>main-account.liquid</strong> template</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/codepasting.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/codepasting.webp" alt="sp-seller.webkul.com_admin_index.php_pinstruction"></a></p><h2 id="code-for-online-store-2-0" tabindex="-1">Code For Online Store 2.0 <a class="header-anchor" href="#code-for-online-store-2-0" aria-label="Permalink to &quot;Code For Online Store 2.0&quot;">​</a></h2><p>If you are using Online Store 2.0 (Example- Dawn), the codes to show the chatbox will remain the same.</p><h2 id="marketplace-seller-panel" tabindex="-1">Marketplace Seller Panel <a class="header-anchor" href="#marketplace-seller-panel" aria-label="Permalink to &quot;Marketplace Seller Panel&quot;">​</a></h2><p>On the marketplace seller panel, a seller needs to visit <strong>Configuration</strong> &gt; <strong>Seller Buyer Chat</strong>:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatmenu.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatmenu.webp" alt="image-30"></a></p><p>Lastly, enable the option &amp; save the changes:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/sbchat.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/sbchat.webp" alt="image-31"></a></p><p>Once done, an operator account will be created for the seller. The seller will receive an email regarding the same with login credentials.</p><h2 id="chat-box-on-storefront" tabindex="-1">Chat Box on Storefront <a class="header-anchor" href="#chat-box-on-storefront" aria-label="Permalink to &quot;Chat Box on Storefront&quot;">​</a></h2><p>You will have the chat widget on the bottom of the page (depending on the configuration):</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/image-32-1200x597.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/image-32-1200x597.png" alt="image-32"></a></p><p>Customers can send their queries in this chat box:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/image-33.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/image-33.png" alt="image-33"></a></p><p>The operators/sellers will monitor it from the ChatWhizz backend.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/image-34-1200x590.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/image-34-1200x590.png" alt="image-34"></a></p><p><strong>Note</strong>: Suppose a customer is on the product description page of product A. If the customer initiates the chat from this page, the seller selling product A will receive the message.</p><p>Similarly, the product page from where the chat starts will decide which seller will get the chat notification.</p><p>Now, in case the customer is on any other page that is not a product page, the chat notification will go to the admin. The admin needs to conduct the chat in that case.</p><h2 id="show-chat-history-to-customers" tabindex="-1">Show chat history to customers <a class="header-anchor" href="#show-chat-history-to-customers" aria-label="Permalink to &quot;Show chat history to customers&quot;">​</a></h2><p>Now, you can show chat history to your customers on their account page. For this, firstly admin needs to regenerate the file from the storefront configuration</p><p>Multivendor marketplace admin panel&gt;&gt;Configuration&gt;&gt;Storefront configuration&gt;&gt; regenerate Seller buyer chat</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/regenarate.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/regenarate.webp" alt="screenshot_1706078483020"></a></p><p>A page named &quot;Seller Buyer Chat&quot; will be created on the Shopify pages section.</p><p><strong>NOTE-</strong> Make sure to add the code to the respective liquid file on Shopify as <a href="https://webkul.com/blog/chatwhizz-seller-buyer-chat-integration/#code-instructions" target="_blank" rel="noreferrer"><strong>mentioned above</strong></a>.</p><h2 id="seller-end" tabindex="-1">SELLER END <a class="header-anchor" href="#seller-end" aria-label="Permalink to &quot;SELLER END&quot;">​</a></h2><p>On the seller&#39;s end, a chat widget will appear in the dashboard like this.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/widget.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/widget.webp" alt="screenshot_1706078731815"></a></p><p><strong>NOTE- To show the chat widget on the seller dashboard make sure that seller-buyer chat is enabled for that particular seller.</strong></p><p>Seller can accept/decline the chat and can create a ticket or end chat of an ongoing chat.</p><p>Enable UV desk addon on chatwhizz end for ticket creation.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chat.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chat.webp" alt="screenshot_1706078973827"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatbox.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/12/chatbox.webp" alt="screenshot_1706079009778"></a></p><h2 id="on-customer-end" tabindex="-1">On customer end <a class="header-anchor" href="#on-customer-end" aria-label="Permalink to &quot;On customer end&quot;">​</a></h2><p>This is how it will look on the customer end</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/01/screenshot_1706088448749-1200x575.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/01/screenshot_1706088448749-1200x575.png" alt="screenshot_1706088448749"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/01/screenshot_1706088463155-1200x575.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/01/screenshot_1706088463155-1200x575.png" alt="screenshot_1706088463155"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/01/seller-buyer-chat.myshopify.com_pages_seller-buyer-chat_clientId65b0d6fa1a4d0420fc29f108-1200x942.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2024/01/seller-buyer-chat.myshopify.com_pages_seller-buyer-chat_clientId65b0d6fa1a4d0420fc29f108-1200x942.png" alt="seller-buyer-chat.myshopify.com_pages_seller-buyer-chat_clientId65b0d6fa1a4d0420fc29f108"></a></p><h2 id="auto-bot-response-seller-buyer-chat" tabindex="-1"><strong>Auto Bot Response (Seller-Buyer Chat)</strong> <a class="header-anchor" href="#auto-bot-response-seller-buyer-chat" aria-label="Permalink to &quot;**Auto Bot Response (Seller-Buyer Chat)**&quot;">​</a></h2><p>We have added a new feature in your seller-buyer chat — <strong>Auto Bot Response</strong>.</p><p>This feature allows your store to automatically reply to customer queries.</p><p>Whenever a customer visits your website and opens the chat, the bot will respond to <strong>product-related</strong> and <strong>order-related</strong> questions based on your store data.</p><p><strong>Add Your Domain</strong></p><ol><li>Go to:<br><strong>Chatwhizz Dashboard → Domain → Add New</strong></li><li>Fill in the details: <ul><li><strong>Domain Name</strong> → Enter your website URL (without  https://)</li><li><strong>Email</strong> → Enter your email ID</li></ul></li><li>Click on <strong>Create</strong></li></ol><p>After this, your domain will be successfully added to the list.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prera.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prera.webp" alt="domain"></a></p><p><strong>Enable Auto Response</strong></p><ol><li>After adding the domain, click on the <strong>Eye Icon</strong> next to it</li></ol><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/kkkkkkk.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/kkkkkkk.webp" alt="image"></a></p><ol start="2"><li>Open <strong>General Configuration</strong></li><li>Find the option: <strong>Enable Auto Response</strong><ul><li>Turn it <strong>ON</strong></li></ul></li><li>You will see this message:<br><em>“Please configure the Auto Response section first, to ensure proper bot functionality.”</em></li></ol><p>This means you now need to complete the setup.</p><ol start="5"><li>Click on <strong>Save</strong></li></ol><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/saedkj.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/saedkj.webp" alt="image"></a></p><p>After saving, a new section <strong>“Auto Response”</strong> will appear.</p><h2 id="configure-auto-response-very-important-step" tabindex="-1"><strong>Configure Auto Response (Very Important Step)</strong> <a class="header-anchor" href="#configure-auto-response-very-important-step" aria-label="Permalink to &quot;**Configure Auto Response (Very Important Step)**&quot;">​</a></h2><p>Go to the <strong>Auto Response section</strong> and fill all details carefully:</p><ul><li><strong>Platform</strong> → Select <strong>Shopify</strong></li><li><strong>AI Agent</strong> → Select <strong>ChatGPT</strong></li><li><strong>API URL</strong> →<br> You must enter this exact URL (do not change anything):<br><a href="https://api.openai.com/v1/chat/completions" target="_blank" rel="noreferrer">https://api.openai.com/v1/chat/completions</a></li><li><strong>API Key</strong> → Paste your OpenAI API Key here</li><li><strong>Response Type</strong> → Select <strong>POST</strong></li></ul><p>After filling all details, click on <strong>Save Changes</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/firt.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/firt.webp" alt="image"></a></p><h2 id="how-to-get-openai-api-key" tabindex="-1"><strong>How to Get OpenAI API Key</strong> <a class="header-anchor" href="#how-to-get-openai-api-key" aria-label="Permalink to &quot;**How to Get OpenAI API Key**&quot;">​</a></h2><p>This step is required for bot functionality.</p><ol><li>Go to: <a href="https://platform.openai.com/" target="_blank" rel="noreferrer">https://platform.openai.com/</a></li><li>Create a new account or login</li><li>Go to <strong>API Keys section</strong></li><li>Click on <strong>Create API Key</strong></li><li>Enter: <ul><li>Name</li><li>Project</li></ul></li><li>Click on <strong>Create Secret Key</strong></li></ol><p>A key will be generated<br> Copy this key and paste it into Chatwhizz (API Key field)</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prera-1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prera-1.webp" alt="opem"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prera2.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prera2.webp" alt="api"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/jhsjsdkljkljasdkjfksajdfs.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/jhsjsdkljkljasdkjfksajdfs.webp" alt="key "></a></p><h2 id="install-the-chatwhizz-live-chat-app-in-shopify" tabindex="-1"><strong>Install the Chatwhizz live chat App in Shopify</strong> <a class="header-anchor" href="#install-the-chatwhizz-live-chat-app-in-shopify" aria-label="Permalink to &quot;**Install the Chatwhizz live chat App in Shopify**&quot;">​</a></h2><ol><li>Open <strong>Shopify App Store</strong></li><li>Search: <strong><a href="https://apps.shopify.com/chatwhizz-live-chat?st_source=autocomplete&amp;surface_detail=autocomplete_apps" target="_blank" rel="noreferrer">Chatwhizz Live Chat</a></strong></li><li>Click on <strong>Install</strong></li></ol><p>This app is <strong>free</strong>, no extra payment required.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/newwww.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/newwww.webp" alt="install"></a></p><ol start="4"><li>After installation: <ul><li>You will see <strong>Choose Your Chat Mode</strong></li><li>Select <strong>Seller Buyer Chat</strong></li><li>Click <strong>Continue</strong></li></ul></li></ol><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prer.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/prer.webp" alt="choose mode"></a></p><p>Once done, Auto Bot functionality will be activated.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/pereir.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/pereir.webp" alt="activated"></a></p><p><strong>Frontend (What Customer Will See)</strong></p><ul><li>A <strong>chat icon</strong> will appear on your website</li><li>A <strong>default welcome message</strong> will be shown</li></ul><p>Customers can:</p><ul><li>Ask product-related questions</li><li>Ask order-related queries</li></ul><p>Bot will automatically respond based on your store data</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/dafsdfasdf.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/dafsdfasdf.webp" alt="frontend"></a></p><p><strong>Edit Default Welcome Message</strong></p><p>If you want to change the message shown to customers:</p><ol><li>Go to:<br><strong>Chatwhizz Panel → Domain → Eye Icon</strong></li><li>Open:<br><strong>Custom Message → Bot Operator</strong></li><li>Click on <strong>Edit</strong></li><li>Update the message as per your requirement and save</li></ol><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/dfasdfasdfasdfasf.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/04/dfasdfasdfasdfasf.webp" alt="custom message"></a></p>',120)])])}const b=t(l,[["render",n]]);export{d as __pageData,b as default};
